import os,json,subprocess,re,datetime
from pathlib import Path
P=Path
def run(a,t=12):
 try:
  r=subprocess.run(a,capture_output=True,text=True,timeout=t)
  return {'rc':r.returncode,'out':r.stdout.strip()}
 except Exception as e:return {'rc':99,'error':type(e).__name__,'out':''}
def scan(p):
 x=P(p)
 if x.is_symlink():
  return {'type':'symlink','target':os.readlink(x)}
 if x.is_file():
  return {'type':'file','size_bytes':x.stat().st_size}
 if not x.is_dir():
  return {'type':'absent'}
 try:
  ls=list(x.iterdir())
  count=sum(z.is_dir() for z in ls)
  files=sum(z.is_file() for z in ls)
  sz=run(['du','-sx','-B1',str(x)],12)
  amount=int(sz['out'].split()[0]) if sz['rc']==0 else None
  return {'type':'directory','subdirs':count,'files':files,'disk_bytes':amount}
 except Exception as e:return {'type':'directory','error':type(e).__name__}
root=P('/root/project-secrets')
secret_folders=sorted(x.name for x in root.iterdir() if x.is_dir()) if root.is_dir() else []
names=['.ansible','.cache/rea','.cache/rea/hopper-releases','.claude-flow','.claude-server-commander','.codex','.dotnet','.gemini','.local/share/rea-github-transport','.npm','.pm2','.prefect','antigravity-workspace','github-2fa-upload','.pink-owner-signing-inbox-20261016','.local/share/motor-ferrari']
h={n:scan(P('/home/ubuntu')/n) for n in names}
r={n:scan(root/n) for n in secret_folders}
scanned=[]
for proc in P('/proc').iterdir():
 if not proc.name.isdigit():continue
 try:
  cwd=os.readlink(proc/'cwd')
  exe=os.readlink(proc/'exe')
  c=(proc/'comm').read_text().strip()
  hits=[]
  for prefix in ['/home/ubuntu/.pm2','/home/ubuntu/.claude-flow','/home/ubuntu/.claude-server-commander','/home/ubuntu/antigravity-workspace','/home/ubuntu/.local/share/rea-github-transport','/root/project-secrets','/srv/projects/Engenheira-reversa','/srv/projects/REA-Trial','/opt/hopper']:
   if cwd.startswith(prefix+'/') or cwd==prefix or exe.startswith(prefix+'/') or exe==prefix:hits.append(prefix)
  if hits:scanned.append({'comm':c,'pid':int(proc.name),'matches':hits})
 except Exception:pass
roots=[]
for parent in ['/etc/systemd/system','/etc/nginx/sites-enabled']:
 p=P(parent)
 if not p.is_dir():continue
 for f in p.iterdir():
  try:
   if not f.is_file():continue
   raw=f.read_text(errors='ignore')
   paths=sorted(set(re.findall(r'/(?:home/ubuntu|root/project-secrets|srv|opt|var/www)/[A-Za-z0-9_+./-]+',raw)))
   bad=[x for x in paths if x.startswith('/root/project-secrets') or x.startswith('/home/ubuntu') or (x.startswith('/srv/') and not x.startswith('/srv/projects/')) or x.startswith('/opt/')]
   if bad:roots.append({'unit_or_site':f.name,'external_references':bad[:25]})
  except Exception:pass
hopper=run(['dpkg-query','-W','hopper'],12)
hopperfiles=run(['dpkg-query','-L','hopper'],12)
npmroot=run(['npm','root','-g'],12)
res={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'external_secret_folder_names':secret_folders,'external_secret_folder_metadata':r,'ubuntu_home_metadata':h,'processes_using_external_installation_dirs':scanned,'systemd_nginx_external_path_refs':roots[:90],'global_hopper_package':hopper['out'] if hopper['rc']==0 else None,'global_hopper_files':hopperfiles['out'].splitlines()[:60] if hopperfiles['rc']==0 else [],'npm_global_root':npmroot['out'] if npmroot['rc']==0 else None,'pm2_global_binary_present':P('/usr/bin/pm2').is_file()}
print(json.dumps(res,ensure_ascii=False,separators=(',',':')))
